import{_ as c,C as t,c as a,o as r,aa as i,G as d}from"./chunks/framework.Cn7WEiMX.js";const g="/assets/builtin-marker-icons.NpwPbmdd.png",h=JSON.parse('{"title":"标记点用法","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/setup/guides/using-markers.md","filePath":"wiki/Dynmap/setup/guides/using-markers.md"}'),s={name:"wiki/Dynmap/setup/guides/using-markers.md"};function p(n,e,m,u,k,D){const o=t("NolebaseGitContributors"),l=t("NolebaseGitChangelog");return r(),a("div",null,[e[0]||(e[0]=i('<h1 id="标记点用法" tabindex="-1">标记点用法 <a class="header-anchor" href="#标记点用法" aria-label="Permalink to &quot;标记点用法&quot;">​</a></h1> <p>Dynmap 支持在地图的原本渲染内容之上增添新的组件。它一般指标记点（Markers），包含标记（图标）、标记区域及多段线标记。</p> <h2 id="标记点组" tabindex="-1">标记点组 <a class="header-anchor" href="#标记点组" aria-label="Permalink to &quot;标记点组&quot;">​</a></h2> <p>标点以集合的方式收纳与组织，即标记点组（Marker Sets）。每组标点都有自己的标签，可通过网页客户端的层级选择器选中。每个标记点都有特定的标记点组。插件自带一个标记点组，即“Markers”标签，用于指代不属于任何分组的标记点。删除标记点组会一并删除组内包含的所有标记点。</p> <p>可以通过 <code>/dmarker addset &lt;标记点组标签&gt; &lt;标记点组名称&gt;</code> 或 <code>/dmarker addset id: &lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 命令新建标记点组。多出的参数可以用来详细设置标记组：</p> <ul><li><code>prio: &lt;数字&gt;</code> 用于决定它在层级选择器中相对其他组别的顺序；</li> <li><code>hide: &lt;true/false&gt;</code> 用于决定它是否默认在地图上可见；</li> <li><code>minzoom: &lt;数字&gt;</code> 用于决定它在小于指定缩放等级之前隐藏。</li></ul> <p>可以通过 <code>/dmarker updateset &lt;标记点组标签&gt; &lt;标记点组名称&gt;</code> 或 <code>/dmarker updateset id: &lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 命令修改现存的标记点组。同样支持上述的 <code>prio:&lt;数字&gt;</code>、<code>hide:&lt;true/false&gt;</code> 参数，另外还有一个 <code>newlabel:&lt;修改后的标签名称&gt;</code> 参数可以用来修改标签名称。</p> <p>在 0.32 版本后，新增了 <code>showlabels:&lt;true/false/null&gt;</code> 参数。这个设置可以显示或隐藏标记点标签（隐藏时只会在鼠标靠近时显示标签）。<code>null</code> 表示全局默认值（在 <code>configuration.txt</code> 下标记点组件部分的 <code>showlabels</code> 处设置）。</p> <p>标记点组（除了默认的标记点组“Markers”）都可以用命令 <code>/dmarker deleteset &lt;标记点组标签&gt; &lt;标记点组名称&gt;</code> 或 <code>/dmarker deleteset id: &lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 删除。</p> <h2 id="标记点" tabindex="-1">标记点 <a class="header-anchor" href="#标记点" aria-label="Permalink to &quot;标记点&quot;">​</a></h2> <p>标记点是最普通的地图标记——一个图标搭配标签，以及相关的描述。每个标记都在世界上有对应位置（XYZ 坐标，及所在世界的 ID），一个标记图标 ID，以及一段可选描述。标记图标 ID 可以在标准标记 ID 列表中浏览（稍后会显示），或者对应其他已载入的图标（见下文“标记图标”部分）。</p> <p>标记可以通过如下命令新建：</p> <ul><li><code>/dmarker add &lt;标记点标签&gt; icon:&lt;图标 ID&gt; set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> - 必须在游戏内输入，在玩家所处位置新建一个标记点。如果不填标记点组 ID，那么它会进入默认分组，即“Markers”。若不填图标 ID，则使用默认图标（“房屋”）。</li> <li><code>/dmarker add id:&lt;标记点 ID&gt; &lt;标记点标签&gt; icon:&lt;图标 ID&gt; set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt; x:&lt;x 轴坐标&gt; y:&lt;y 轴坐标&gt; z:&lt;z 轴坐标&gt; world:&lt;世界名称&gt;</code> - 作用同上，但为标记设置了 ID，且可通过控制台执行。</li> <li><code>使用告示牌</code>：若标记点组件的 <code>enablesigns</code> 设置开启，那么玩家可以在拥有适当权限（<code>dynmap.marker.sign</code>）的前提下创建带有告示牌标签的标记点。告示牌的第一行需以 <code>[dynmap]</code> 开头。下面几行除了 <code>set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code>（用于将标记点归为指定组别）或 <code>icon:&lt;图标 ID&gt;</code>（允许玩家设置标记点图标，未设置时为“告示牌”图标）之外的内容都会当做标记点的描述文本。成功创建以后，告示牌上的 <code>[dynmap]</code>、<code>set:</code> 以及 <code>icon:</code> 参数会消失。若之后破坏告示牌，对应的标记点也会一并消失。</li></ul> <p>创建之后，标记点可以通过如下命令编辑：</p> <ul><li><code>/dmarker movehere &lt;标记点标签&gt; set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 或 <code>/dmarker movehere id:&lt;标记点 ID&gt; set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code>：将现有标记点移动到玩家所在位置。注意：若需要选择不在默认标记点组（“Markers”）中的标记点，必须填入 <code>标记点组 ID</code> 参数。</li> <li><code>/dmarker update &lt;标记点标签&gt; set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt; icon:&lt;图标 ID&gt; newlabel:&lt;新标签&gt;</code> 或 <code>/dmarker update id:&lt;标记点 ID&gt; set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt; icon:&lt;图标 ID&gt; newlabel:&lt;新标签&gt;</code>。注意：若需要选择不在默认标记点组（“Markers”）中的标记点，必须填入 <code>标记点组 ID</code> 参数——默认标记点组本身的名字无法更改。</li></ul> <p>如果需要给标记点添加描述，首先需要用 <code>/dmarker resetdesc id:&lt;标记点 ID&gt; set:&lt;组别 ID&gt;</code> 重置标记点的描述，然后再通过命令 <code>/dmarker appenddesc id:&lt;标记点 ID&gt; set:&lt;组别 ID&gt; desc:&quot;&lt;标记点描述&gt;&quot;</code> 为其增加描述。确保描述部分用英文双引号（<code>&quot;&quot;</code>）包裹。</p> <p>标记点可以通过 <code>/dmarker delete &lt;标记点标签&gt;&lt;/marker&gt; set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 或 <code>/dmarker delete id:&lt;标记点 ID&gt; set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 命令删除。</p> <p>现存的标记点组以及它们的属性可通过命令 <code>/dmarker listsets</code> 浏览。</p> <p>现存的标记点以及它们的属性则可通过命令 <code>/dmarker list set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 浏览。</p> <h2 id="标记点图标" tabindex="-1">标记点图标 <a class="header-anchor" href="#标记点图标" aria-label="Permalink to &quot;标记点图标&quot;">​</a></h2> <p>标记点图标是用于显示标注标记点的图片资源。Dynmap 自带一个标准的图标包，详见下图，总是可以使用与设置，且无法删除。完整图标列表可在游戏内通过 <code>/dmarker icons</code> 命令浏览。</p> <p>新图标可通过如下方式安装：</p> <ul><li>复制 PNG 格式的图片，放入 Bukkit 服务器的文件系统。图片的边长应该为 8、16 或 32 像素。</li> <li>输入命令 <code>/dmarker addicon id:&lt;图标 ID&gt; &lt;图标标签&gt; file:&lt;指向图片的路径&gt;</code>——如果命令执行完成，那么图标就算导入成功（不需要留在原本复制的地方）。</li></ul> <p>若要更新现存图标的样式，只需输入命令 <code>/dmarker updateicon id:&lt;图标 ID&gt; newlabel:&lt;新标签&gt; file:&lt;指向图片的路径&gt;</code> 即可。</p> <p>若要删除现存图标，只需输入命令 <code>/dmarker deleteicon id:&lt;图标 ID&gt;</code> 即可。</p> <figure><img src="'+g+'" alt="" tabindex="0"><figcaption>内置标记点图标，由 Blankplanet 绘制！</figcaption></figure> <h2 id="区域标记" tabindex="-1">区域标记 <a class="header-anchor" href="#区域标记" aria-label="Permalink to &quot;区域标记&quot;">​</a></h2> <p>区域标记可以在地图上描绘出平面或立体范围。通过两组以上 XZ 轴坐标的区域标记形成的闭合区域，形状一般为矩形（只设置两点的情况下，以两点连线为对角线构成的矩形）或多边形（设置三个以上点，首尾相连构成的图形）。另外，可以提供 Y 值的上下限，将平面图形扩展为立体范围（顶面与底面水平）。</p> <p>区域的边框属性有颜色（HEX 格式：RRGGBB）、描边宽度及不透明度。内部区域的属性则有填充色（HEX 格式：RRGGBB）及填充不透明度。</p> <p>创建区域前需要先设置角点。可以这样：</p> <ul><li>输入 <code>/dmarker addcorner</code> 在玩家所处位置插下角点。</li> <li>输入 <code>/dmarker addcorner &lt;x&gt; &lt;y&gt; &lt;z&gt;</code> 或 <code>/dmarker addcorner &lt;x&gt; &lt;y&gt; &lt;z&gt; &lt;世界名称&gt;</code> 在指定位置插下角点。</li></ul> <p>若需要，还可以输入命令 <code>/dmarker cleancorners</code> 清除插下的所有角点。</p> <p>插入所有角点后，可通过 <code>/dmarker addarea set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 或 <code>/dmarker addarea id:&lt;标记点 ID&gt; set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 设置区域。这些命令可以设置额外参数，或者之后也可以用 <code>/dmarker updatearea id:&lt;标记点 ID&gt; set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 或 <code>/dmarker updatearea set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt; newset:&lt;新标记点组 ID&gt;</code> 命令追加。完整设置如下：</p> <ul><li><code>color</code> - 边框颜色（<code>color:RRGGBB</code>）</li> <li><code>fillcolor</code> - 填充颜色（边框范围内的颜色）（<code>fillcolor:RRGGBB</code>）</li> <li><code>opacity</code> - 边框不透明度（<code>0.0</code> = 完全透明，<code>1.0</code> = 不透明）</li> <li><code>fillopacity</code> - 填充不透明度（<code>0.0</code> = 完全透明，<code>1.0</code> = 不透明）</li> <li><code>weight</code> - 边框宽度（<code>0</code> = 最细，值越高越粗）</li> <li><code>ytop</code> - 区域顶部上限（默认为 64）</li> <li><code>ybottom</code> - 区域底部下限（默认为 64）</li></ul> <div class="info custom-block"><p class="custom-block-title">注意</p> <p>现存区域的边角目前无法更新——只能删除当前区域重新创建解决。另外，角点列表会在通过命令 <code>/dmarker addarea</code> 创建区域后清空。</p></div> <p>若要删除现有的区域标记点，输入命令 <code>/dmarker deletearea id:&lt;标记点 ID&gt; set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 即可。</p> <p>现存区域及其属性可通过 <code>/dmarker listareas set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 命令浏览。</p> <h2 id="圆形标记" tabindex="-1">圆形标记 <a class="header-anchor" href="#圆形标记" aria-label="Permalink to &quot;圆形标记&quot;">​</a></h2> <p>圆形标记用于在地图上显示平面圆形（或椭圆形）区域。区域由中心点（xyz 坐标）及半径（通过 <code>radius</code> 参数指定）或 X 与 Z 轴的半径（椭圆，通过 <code>radiusx</code> 和 <code>radiusz</code> 参数指定）。</p> <p>圆形区域的边框属性有颜色（HEX 格式：RRGGBB）、描边宽度及不透明度。内部区域的属性则有填充色（HEX 格式：RRGGBB）及填充不透明度。</p> <p>圆形标记点可通过 <code>/dmarker addcircle &lt;圆形区域标签&gt; set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 或 <code>/dmarker addcircle id:&lt;圆形区域 ID&gt; &lt;圆形区域标签&gt; set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 命令创建。这些命令可以设置额外参数，或者之后也可以用 <code>/dmarker updatecircle id:&lt;圆形区域 ID&gt; set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 或 <code>/dmarker updatecircle &lt;圆形区域标签&gt; set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 命令追加。完整设置如下：</p> <ul><li><code>x</code> - 中心点 X 轴坐标（默认为玩家所在位置）</li> <li><code>y</code> - 中心点 Y 轴坐标（默认为玩家所在位置）</li> <li><code>z</code> - 中心点 Z 轴坐标（默认为玩家所在位置）</li> <li><code>radius</code> - 区域半径（默认为 <code>1</code>）</li> <li><code>radiusx</code> - 区域 X 轴半径（默认为 <code>1</code>）</li> <li><code>radiusy</code> - 区域 Z 轴半径（默认为 <code>1</code>）</li> <li><code>world</code> - 世界中心点（默认为玩家所在位置）</li> <li><code>color</code> - 边框颜色（格式为 <code>color:RRGGBB</code>）</li> <li><code>fillcolor</code> - （边框内区域）填充颜色（格式为 <code>fillcolor:RRGGBB</code>）</li> <li><code>opacity</code> - 边框不透明度（<code>0.0</code> = 完全透明，<code>1.0</code> = 不透明）</li> <li><code>fillopacity</code> - 填充不透明度（<code>0.0</code> = 完全透明，<code>1.0</code> = 不透明）</li> <li><code>weight</code> - 边框宽度（<code>0</code> = 最细，值越高越粗）</li></ul> <p>若要删除圆形区域，只需输入 <code>/dmarker deletecircle id:&lt;圆形区域 ID&gt; set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 命令即可。</p> <p>现存圆形区域及其属性可通过 <code>/dmarker listcircles set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 命令浏览。</p> <h2 id="多边形标记" tabindex="-1">多边形标记 <a class="header-anchor" href="#多边形标记" aria-label="Permalink to &quot;多边形标记&quot;">​</a></h2> <p>多边形标记用于在地图上显示多边形区域。每个多边形标记点都由一或多个 XYZ 坐标表示，带有标签及可选的描述，及相关的边框颜色、宽度和不透明度。</p> <p>圆形区域的边框属性有颜色（HEX 格式：RRGGBB）、描边宽度（0-N）及不透明度。内部区域的属性则有填充色（HEX 格式：RRGGBB）及填充不透明度（0.0-1.0）。</p> <p>创建区域前需要先设置角点。可以这样：</p> <ul><li>输入 <code>/dmarker addcorner</code> 在玩家所处位置插下角点。</li> <li>输入 <code>/dmarker addcorner &lt;x&gt; &lt;y&gt; &lt;z&gt;</code> 或 <code>/dmarker addcorner &lt;x&gt; &lt;y&gt; &lt;z&gt; &lt;世界名称&gt;</code> 在指定位置插下角点。</li></ul> <p>若需要，还可以输入命令 <code>/dmarker cleancorners</code> 清除插下的所有角点。</p> <p>插入所有角点后，可通过 <code>/dmarker addline &lt;多边形区域标签&gt; set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 或 <code>/dmarker addline id:&lt;多边形区域 ID&gt; &lt;多边形区域标签&gt; set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 设置区域。这些命令可以设置额外参数，或者之后也可以用 <code>/dmarker updateline id:&lt;多边形区域 ID&gt; set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 或 <code>/dmarker updateline &lt;多边形区域标签&gt; set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 命令追加。完整设置如下：</p> <ul><li><code>color</code> - 边框颜色（格式为 <code>color:RRGGBB</code>）</li> <li><code>opacity</code> - 边框不透明度（<code>0.0</code> = 完全透明，<code>1.0</code> = 不透明）</li> <li><code>weight</code> - 边框宽度（<code>0</code> = 最细，值越高越粗）</li></ul> <div class="info custom-block"><p class="custom-block-title">注意</p> <p>现存多边形区域的边角目前无法更新——只能删除当前区域重新创建解决。另外，角点列表会在通过命令 <code>/dmarker addarea</code> 创建区域后清空。</p></div> <p>若要删除现有的区域标记点，输入命令 <code>/dmarker deleteline id:&lt;多边形区域 ID&gt; set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 即可。</p> <p>现存区域及其属性可通过 <code>/dmarker listlines set:&lt;标记点组 ID&gt; &lt;标记点组名称&gt;</code> 命令浏览。</p> ',110)),d(o),d(l)])}const b=c(s,[["render",p]]);export{h as __pageData,b as default};
